constraints:
1 ≤ |S| ≤ 10^{5}

expected time complexity: O(|S|)
expected auxiliary space: O(|S|)

standard_solution_code:
class Solution:

	def maxLength(self, S):
		stack = []
		max_length = 0
		start_index = 0
		for i in range(len(S)):
			if S[i] == '(':
				stack.append(i)
			elif not stack:
				start_index = i + 1
			else:
				stack.pop()
				if not stack:
					max_length = max(max_length, i - start_index + 1)
				else:
					max_length = max(max_length, i - stack[-1])
		return max_length
